<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $seed = json_decode(file_get_contents(__DIR__."/../scratch_seed.json"), true); foreach($seed["poaActions"] as $pa) { $area = $pa["areaId"]; $number = $pa["number"]; $areaIds = ["PRES"=>1, "SG"=>2, "SA"=>3, "DRH"=>4, "DRMySG"=>5, "CI"=>6, "DGJ"=>7, "CCSyRP"=>8, "CTyDP"=>9, "IFyC"=>10, "CCLA"=>11, "USI"=>12, "UEyJ"=>13, "CDyP"=>14, "CA"=>15, "CDHyG"=>16, "DPPCyPD"=>17, "CVyRI"=>18, "UEPS"=>19, "PAAH"=>20, "PJHR"=>21, "POVR"=>22, "PKSL"=>23, "PLPJC"=>24]; $urgId = $areaIds[$area] ?? null; if(!$urgId) continue; $dbAct = Illuminate\Support\Facades\DB::table("acciones_sustantivas")->join("proyectos", "acciones_sustantivas.proyecto_id", "=", "proyectos.proyecto_id")->join("responsables_operativos", "proyectos.responsable_operativo_id", "=", "responsables_operativos.responsable_operativo_id")->where("proyectos.ejercicio_id", 17)->where("responsables_operativos.unidad_responsable_gasto_id", $urgId)->where("acciones_sustantivas.numero", $number)->select("acciones_sustantivas.accion_sustantiva_id")->first(); if(!$dbAct) { $dbAct = Illuminate\Support\Facades\DB::table("actividades_sustantivas")->join("proyectos", "actividades_sustantivas.proyecto_id", "=", "proyectos.proyecto_id")->join("responsables_operativos", "proyectos.responsable_operativo_id", "=", "responsables_operativos.responsable_operativo_id")->where("proyectos.ejercicio_id", 17)->where("responsables_operativos.unidad_responsable_gasto_id", $urgId)->where("actividades_sustantivas.numero", $number)->select("actividades_sustantivas.id as accion_sustantiva_id")->first(); } if($dbAct) { $actId = $dbAct->accion_sustantiva_id; Illuminate\Support\Facades\DB::table("acciones_sustantivas")->where("accion_sustantiva_id", $actId)->update(["descripcion" => $pa["text"]]); Illuminate\Support\Facades\DB::table("actividades_sustantivas")->where("id", $actId)->update(["descripcion" => $pa["text"], "denominacion" => $pa["text"]]); foreach($seed["risks"] as $r) { if(in_array($pa["id"], $r["linkedActionIds"] ?? [])) { $riesgo = Illuminate\Support\Facades\DB::table("riesgos")->where("local_id", $r["id"])->first(); if($riesgo) { Illuminate\Support\Facades\DB::table("actividad_riesgo")->updateOrInsert(["actividad_sustantiva_id" => $actId, "riesgo_id" => $riesgo->id]); echo "Linked " . $r["id"] . " to $actId\n"; } } } } else { echo "Not found act for Area $area, Number $number\n"; } }
